private fun RedisClient.stat(field: String): Long {
    val section = if (field.startsWith("used_memory")) "memory" else "stats"
    return info(section).lineSequence().map { it.trim() }.first { it.startsWith("$field:") }.substringAfter(':').toLong()
}

